CustomField.formula:
IF(
  ISBLANK(Quickbase_ID_URL__c),
  "",
  IF(
    CONTAINS(Quickbase_ID_URL__c, "rid="),

    /* CASE 1: extract from rid= */
    LEFT(
      MID(
        Quickbase_ID_URL__c,
        FIND("rid=", Quickbase_ID_URL__c) + 4,
        LEN(Quickbase_ID_URL__c)
      ),
      FIND("_", MID(
        Quickbase_ID_URL__c,
        FIND("rid=", Quickbase_ID_URL__c) + 4,
        LEN(Quickbase_ID_URL__c)
      ) & "_") - 1
    ),

    /* CASE 2: fallback – number before _HL_ */
    LEFT(
      Quickbase_ID_URL__c,
      FIND("_", Quickbase_ID_URL__c & "_") - 1
    )
  )
)
